                writer.WriteBoolean("writable", agentDef.WritableOption.Value!.Value);

            if (agentDef.EngineOption.IsSet)
            {
                writer.WritePropertyName("engine");
                JsonSerializer.Serialize(writer, agentDef.Engine, jsonSerializerOptions);
            }
            if (agentDef.GrantsOption.IsSet)
            {
                writer.WritePropertyName("grants");
                JsonSerializer.Serialize(writer, agentDef.Grants, jsonSerializerOptions);
            }
            if (agentDef.SkillsOption.IsSet)
            {
                writer.WritePropertyName("skills");
                JsonSerializer.Serialize(writer, agentDef.Skills, jsonSerializerOptions);
            }
            if (agentDef.PromptCharsOption.IsSet)
                writer.WriteNumber("promptChars", agentDef.PromptCharsOption.Value!.Value);

            if (agentDef.PromptOption.IsSet)
                writer.WriteString("prompt", agentDef.Prompt);

            if (agentDef.WarningsOption.IsSet)
            {
                writer.WritePropertyName("warnings");
                JsonSerializer.Serialize(writer, agentDef.Warnings, jsonSerializerOptions);
            }
            if (agentDef.ScannedOption.IsSet)
            {
                writer.WritePropertyName("scanned");
                JsonSerializer.Serialize(writer, agentDef.Scanned, jsonSerializerOptions);
            }
        }
    }
}
